var sourceScene=UnityEditor.SceneManagement.EditorSceneManager.OpenPreviewScene("Assets/Test/Cheon/Scenes/Test_CheonEnvironmentMap.unity");int replaced=0;string sourcePath="Assets/Prefabs/Environment/SelfModeling/Lantern.prefab";
try{var reference=sourceScene.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).First(t=>t.name=="SelfModeling_Lantern");var prefab=AssetDatabase.LoadAssetAtPath<GameObject>(sourcePath);var parent=GameObject.Find("ApproachLanterns").transform;foreach(Transform root in parent){foreach(var child in root.Cast<Transform>().Where(t=>t.name!="WarmLight").ToArray())UnityEngine.Object.DestroyImmediate(child.gameObject);var model=(GameObject)PrefabUtility.InstantiatePrefab(prefab,root);model.name="ExistingStoneLantern";model.transform.localScale=reference.lossyScale;model.transform.rotation=reference.rotation;var renderers=model.GetComponentsInChildren<Renderer>();var referenceRenderers=reference.GetComponentsInChildren<Renderer>();for(int i=0;i<Mathf.Min(renderers.Length,referenceRenderers.Length);i++)renderers[i].sharedMaterials=referenceRenderers[i].sharedMaterials;var bounds=renderers[0].bounds;foreach(var renderer in renderers.Skip(1))bounds.Encapsulate(renderer.bounds);model.transform.position+=new Vector3(root.position.x-bounds.center.x,root.position.y-bounds.min.y-.02f,root.position.z-bounds.center.z);foreach(var collider in model.GetComponentsInChildren<Collider>())UnityEngine.Object.DestroyImmediate(collider);root.Find("WarmLight").localPosition=Vector3.up*1.2f;PrefabUtility.RecordPrefabInstancePropertyModifications(model.transform);replaced++;}}finally{UnityEditor.SceneManagement.EditorSceneManager.ClosePreviewScene(sourceScene);}
var animation=UnityEngine.Object.FindFirstObjectByType<Cheon.Prototype.MountainPass.PassAnimationController>();var serialized=new SerializedObject(animation);serialized.FindProperty("movingDrawSpeedMultiplier").floatValue=1.9f;serialized.ApplyModifiedPropertiesWithoutUndo();
var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene();UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene);UnityEditor.SceneManagement.EditorSceneManager.SaveScene(scene);return new{replaced,sourcePath,equipmentLayer=serialized.FindProperty("equipmentWhileMoving").boolValue};
